INSERT INTO i18n_messages (key, value_az, value_en, value_ru) VALUES
  ('psychApp.tdbFocusTitle', 'Diqqəti yığ', 'Gather focus', 'Собрать фокус'),
  ('psychApp.tdbIntro', 'Bu seçim psixoloq tövsiyələrinə əsaslanır: video müşayiət rəqabət deyil, dəstəkdir — hisslərini adlandırmağa və günlük balansı qorumağa kömək edir.', 'This selection is grounded in psychologist recommendations: the videos are support, not a substitute — they help you name feelings and protect daily balance.', 'Подборка основана на рекомендациях психологов: видео — это поддержка, а не замена; они помогают называть чувства и сохранять ежедневный баланс.'),
  ('psychApp.tdbIntroEyebrow', 'Seçim haqqında', 'About the selection', 'О подборке'),
  ('psychApp.tdbListEyebrow', 'Videolar', 'Videos', 'Видео'),
  ('psychApp.tdbMetaDescription', 'Psixoloji tövsiyələr üçün seçilmiş TDB videoları.', 'TDB videos selected for psychological recommendations.', 'Видео TDB, отобранные для психологических рекомендаций.'),
  ('psychApp.tdbMetaTitle', 'TDB videoları', 'TDB videos', 'TDB видео'),
  ('psychApp.tdbMinutes', '{count} dəq', '{count} min', '{count} мин'),
  ('psychApp.tdbResetDesc', 'Çətin söhbətdən sonra özünə qayıtmaq üçün 4 dəqiqə.', 'Four minutes to return to yourself after a hard conversation.', 'Четыре минуты, чтобы вернуться к себе после трудного разговора.'),
  ('psychApp.tdbResetTitle', 'Emosional sıfırlama', 'Emotional reset', 'Эмоциональный сброс'),
  ('psychApp.tdbSleepDesc', 'Yatmazdan əvvəl ağır ekransız ritm — yavaş tonlar yuxunu dəvət edir.', 'A screen-slow rhythm before bed — deep tones invite sleep.', 'Медленный ритм перед сном — глубокие тона приглашают сон.'),
  ('psychApp.tdbSleepTitle', 'Yuxuya keçid', 'Transition to sleep', 'Переход ко сну'),
  ('psychApp.tdbStressDesc', 'Gərginlik artdıqda 4 dəqiqəlik vizual müşayiət — nəfəs templə birlikdə yumşalır.', 'A 4-minute visual companion for rising tension — softens in step with your breath.', '4-минутный визуальный спутник при нарастающем напряжении — смягчает в такт дыханию.'),
  ('psychApp.tdbStressTitle', 'Stress dalğasını sakitləşdir', 'Settle the stress wave', 'Успокоить волну стресса'),
  ('psychApp.tdbSubtitle', 'Hər video konkret bir psixoloji tövsiyəni dəstəkləyir — stress, yuxu, fokus və balans üçün seçilib.', 'Each video backs a specific psychological recommendation — chosen for stress, sleep, focus and balance.', 'Каждое видео поддерживает конкретную психологическую рекомендацию — отобрано для стресса, сна, фокуса и баланса.'),
  ('psychApp.tdbTitle', 'Tövsiyə videoları', 'Recommendation videos', 'Видео рекомендаций'),
  ('psychApp.todayEyebrow', 'Bu gün üçün', 'For today', 'На сегодня'),
  ('psychApp.videoEyebrow', 'Video materiallar', 'Video materials', 'Видео материалы'),
  ('psychApp.videoIntro', 'Gözlə üçün sakit rəsmlər — nəfəs ritmi izləmək üçün.', 'Calm visuals for the eyes — to follow the breathing rhythm.', 'Спокойные картинки для глаз — чтобы следовать за ритмом дыхания.'),
  ('psychApp.whatEyebrow', 'Meditasiya nədir', 'What meditation is', 'Что такое медитация'),
  ('psychApp.whatText', 'Meditasiya — zehni indiki ana toplamaq praktikasıdır. Rəqibin yoxdur, uduş yoxdur: yalnız nəfəs, bədən və diqqət. Elmi araşdırmalar müntəzəm praktikanın stress hormonunu azaltdığını, diqqət müddətini uzatdığını və yuxu keyfiyyətini yaxşılaşdırdığını göstərir. Gündə beş dəqiqə belə başlamaq üçün kifayətdir.', 'Meditation is the practice of gathering the mind into the present moment. There is no opponent and no win: only breath, body and attention. Research shows a regular practice lowers stress hormones, lengthens attention span and improves sleep quality. Five minutes a day is enough to begin.', 'Медитация — практика собирания ума в настоящий момент. Здесь нет соперника и победы: только дыхание, тело и внимание. Исследования показывают, что регулярная практика снижает гормоны стресса, удлиняет внимание и улучшает качество сна. Пяти минут в день достаточно, чтобы начать.'),
  ('rulesPage.placeholder', 'hello, write this', 'hello, write this', 'hello, write this'),
  ('rulesPage.title', 'Qaydalar', 'Rules', 'Правила'),
  ('sectionRail.close', 'Alt-sekmələri yığ', 'Close sub-sections', 'Свернуть подразделы'),
  ('sectionRail.current', 'Hazırkı:', 'Current:', 'Текущий:'),
  ('sectionRail.label', 'Alt-sekmələr', 'Sub-sections', 'Подразделы'),
  ('sectionRail.open', 'Alt-sekmələri aç', 'Open sub-sections', 'Открыть подразделы'),
  ('sections.backHome', 'Əsas səhifəyə qayıdın', 'Back to Home', 'Вернуться на главную'),
  ('sections.diet.ctaText', 'Bir tarazlıq qabı çox yaxşı bir başlanğıcdır.', 'One balanced bowl is a very good start.', 'Одна сбалансированная тарелка — уже отличное начало.'),
  ('sections.diet.ctaTitle', 'İlk yeməyinizi planlaşdırın', 'Plan your first meal', 'Запланируйте первый приём пищи'),
  ('sections.diet.heroText', 'Bələdçi pərə planları, dürüst reseptlər, etibar etdiyiniz dietoloqlar və yaxşı yeməyi asanlaşdıran videolar — planı tənzimləmək üçün AI ilə.', 'Guided diet plans, honest recipes, dietitians you can trust and videos that make good food feel easy — with AI to adjust the plan.', 'Управляемые планы питания, честные рецепты, заслуживающие доверия диетологи и видео, где хорошая еда — это легко. ИИ подстроит план под вас.'),
  ('sections.diet.heroTitle', 'Sadəcə yaxşı yeyin.', 'Eat well, simply.', 'Ешьте хорошо — просто.'),
  ('sections.diet.items.0.desc', 'Yaşılıqlar, taxıllar, zeytunlar və limon sousu — axşamı sakit saxlayan nahar.', 'Greens, grains, olives and a lemon dressing — a lunch that keeps the afternoon calm.', 'Зелень, злаки, оливки и лимонная заправка — обед, после которого вечер остаётся спокойным.'),
  ('sections.diet.items.0.title', 'Aralıq dənizi taxıl qabası', 'Mediterranean grain bowl', 'Средиземноморский боул'),
  ('sections.diet.items.1.desc', 'Təxminən 30 qram zülallı beş səhər variantı, hamısı on beş dəqiqədən az.', 'Five morning options around 30 g of protein, all under fifteen minutes.', 'Пять утренних вариантов около 30 г белка, каждый — быстрее пятнадцати минут.'),
  ('sections.diet.items.1.title', 'Yüksək zülallı səhərlər', 'High-protein breakfasts', 'Завтраки с высоким белком'),
  ('sections.diet.items.2.desc', 'Leyla Əliyeva, RD. Məşqlərinizə uyğun, əleyhinə deyil, şəxsi planlar.', 'Leyla Aliyeva, RD. Personal plans built around your training, not against it.', 'Leyla Aliyeva, RD. Личные планы, построенные вокруг тренировок, а не против них.'),
  ('sections.diet.items.2.title', 'Dietoloqla məsləhətləşin', 'Consult a dietitian', 'Консультация диетолога'),
  ('sections.diet.items.3.desc', 'Bir alış-veriş torbasından üç şam yeməyi — video bələdçi.', 'A video guide to three dinners from one shopping bag.', 'Видеогид: три ужина из одного пакета продуктов.'),
  ('sections.diet.items.3.title', '20 dəqiqədə yemək hazırlığı', 'Meal prep in 20 minutes', 'Заготовки еды за 20 минут'),
  ('sections.diet.name', 'Qidalanma', 'Diet', 'Питание'),
  ('sections.diet.subs.ai', 'AI', 'AI', 'ИИ'),
  ('sections.diet.subs.diet', 'Qidalanma', 'Diet', 'Питание'),
  ('sections.diet.subs.dietisyenler', 'Dietoloqlar', 'Dietitians', 'Диетологи'),
  ('sections.diet.subs.videolar', 'Videolar', 'Videos', 'Видео'),
  ('sections.eyebrow', 'PreLife · {section}', 'PreLife · {section}', 'PreLife · {section}'),
  ('sections.gym.ctaText', 'Başlamaq üçün bu gün otuz beş dəqiqə kifayətdir.', 'Thirty-five minutes today is enough to start.', 'Тридцати пяти минут сегодня достаточно для старта.'),
  ('sections.gym.ctaTitle', 'İlk məşqiniz sizi gözləyir', 'Your first workout is waiting', 'Первая тренировка уже ждёт'),
  ('sections.gym.heroText', 'GYM planları, yoqa axınları, pilates dərsləri, şəxsi məşqçilər və video məşqlər — PreLife AI həftəni enerjinizə uyğun qurur.', 'GYM plans, yoga flows, pilates classes, personal trainers and video workouts — with PreLife AI building the week around your energy.', 'Программы для зала, йога-потоки, пилатес, личные тренеры и видеотренировки — а PreLife ИИ собирает неделю под вашу энергию.'),
  ('sections.gym.heroTitle', 'Hər gün, öz üsulunuzla hərəkət edin.', 'Move every day, your way.', 'Двигайтесь каждый день — по-своему.'),
  ('sections.gym.items.0.desc', '35 dəqiqəlik GYM sessiyası: beş əsas hərəkət, üç tur, bir düzgün final.', 'A 35-minute GYM session: five compounds, three rounds, one honest finisher.', '35 минут в зале: пять базовых упражнений, три круга, один честный финал.'),
  ('sections.gym.items.0.title', 'Bütün bədən gücü', 'Full-body strength', 'Сила всего тела'),
  ('sections.gym.items.1.desc', 'Gün başlamadan on beş sakit dəqiqə — bel və kalçanı oyadan axın.', 'Fifteen gentle minutes to wake the spine and hips before the day begins.', 'Пятнадцать мягких минут, чтобы разбудить спину и бёдра до начала дня.'),
  ('sections.gym.items.1.title', 'Səhər yoqa axını', 'Morning yoga flow', 'Утренний йога-поток'),
  ('sections.gym.items.2.desc', 'Bir mat, iyirmi dəqiqə və dərin yanğı — hər şeyin təməli.', 'A mat, twenty minutes and a deep burn — the foundation for everything else.', 'Коврик, двадцать минут и глубокое жжение — основа всего остального.'),
  ('sections.gym.items.2.title', 'Pilates nüvə əsasları', 'Pilates core basics', 'Пилатес: база кора'),
  ('sections.gym.items.3.desc', 'Şəxsi məşqçi, güc mütəxəssisi. Təqviminizə hörmət edən proqramlar.', 'Personal trainer and strength specialist. Programs that respect your calendar.', 'Персональный тренер, специалист по силе. Программы, уважающие ваш календарь.'),
  ('sections.gym.items.3.title', 'Elvin ilə məşq edin', 'Train with Elvin', 'Тренируйтесь с Эльвином'),
  ('sections.gym.name', 'İdman', 'Gym', 'Фитнес'),
  ('sections.gym.subs.ai', 'AI', 'AI', 'ИИ'),
  ('sections.gym.subs.gym', 'GYM', 'GYM', 'GYM'),
  ('sections.gym.subs.hocalar', 'Məşqçilər', 'Trainers', 'Тренеры'),
  ('sections.gym.subs.plates', 'Pilates', 'Pilates', 'Пилатес'),
  ('sections.gym.subs.videolar', 'Videolar', 'Videos', 'Видео'),
  ('sections.gym.subs.yoga', 'Yoqa', 'Yoga', 'Йога'),
  ('sections.itemsTitle', 'Hazırda seçilmişlər', 'Featured right now', 'Избранное сейчас'),
  ('sections.library.ctaText', 'Gündə bir səhifə belə ili dəyişir.', 'One page a day already changes the year.', 'Одна страница в день уже меняет год.'),
  ('sections.library.ctaTitle', 'Növbəti fəslinizi açın', 'Open your next chapter', 'Откройте следующую главу'),
  ('sections.library.heroText', 'Həyatın hər mövsümünə uyğun kolleksiyalarla seçilmiş kitabxana — və bu anda yaşadıqlarınıza uyğun AI seçimləri.', 'A curated library with collections for every season of life — and AI picks tuned to what you are living through right now.', 'Библиотека с подборками на каждый сезон жизни — и выбор ИИ, подстроенным под то, что вы переживаете прямо сейчас.'),
  ('sections.library.heroTitle', 'Böyümək üçün oxuyun.', 'Read to grow.', 'Читайте, чтобы расти.'),
  ('sections.library.items.0.desc', 'Ceyms Klir. Kiçik dəyişikliklər, görkəmli nəticələr — hər PreLife planı üçün vərdiş yoldaşı.', 'James Clear. Small changes, remarkable results — the habit-building companion for every PreLife plan.', 'Джеймс Клир. Маленькие изменения, заметные результаты — спутник по привычкам для любого плана PreLife.'),
  ('sections.library.items.0.title', 'Atom vərdişlər', 'Atomic Habits', 'Атомные привычки'),
  ('sections.library.items.1.desc', 'Ekhart Tolle. Mövcudluq bir praktika kimi — meditasiya bölməsi ilə təbii uyğunluq.', 'Eckhart Tolle. Presence as a practice — a natural pair with the meditation section.', 'Экхарт Толле. Присутствие как практика — естественная пара к разделу медитации.'),
  ('sections.library.items.1.title', 'Hazırın gücü', 'The Power of Now', 'Сила настоящего'),
  ('sections.library.items.2.desc', 'Kal Nyuport. Diqqətin paylaşdırıldığı dünyada fokus — sizi həqiqətən irəli aparan iş üçün.', 'Cal Newport. Focus in a distracted world, for work that actually moves you forward.', 'Кэл Ньюпорт. Фокус в мире отвлечений — для работы, которая действительно двигает вас вперёд.'),
  ('sections.library.items.2.title', 'Dərin iş', 'Deep Work', 'Глубокая работа'),
  ('sections.library.items.3.desc', 'PreLife AI-a necə hiss etdiyinizi deyin və həyatınızın bu həftəsinə uyğun üç kitab alın.', 'Tell PreLife AI how you feel and get three books that fit this exact week of your life.', 'Расскажите PreLife ИИ, как себя чувствуете, и получите три книги под эту самую неделю жизни.'),
  ('sections.library.items.3.title', 'Əhvalınıza uyğun AI seçimləri', 'AI picks for your mood', 'Подборки ИИ под настроение'),
  ('sections.library.name', 'Kitablar', 'Books', 'Книги'),
  ('sections.library.subs.ai', 'AI', 'AI', 'ИИ'),
  ('sections.library.subs.kitablar', 'Kitablar', 'Books', 'Книги'),
  ('sections.meditation.ctaText', 'Bu gün yalnız üç dəqiqəlik sakitliklə başlayın.', 'Start with three quiet minutes today.', 'Сегодня достаточно трёх тихих минут.'),
  ('sections.meditation.ctaTitle', 'Daxili işinizə başlayın', 'Begin your inner work', 'Начните внутреннюю работу'),
  ('sections.meditation.heroText', 'Etibarlı psixoloqlarla danışın, bələdçi meditasiyalar edin, videolardan öyrənin və sessiyalar arasında PreLife AI dəstəyi alın — daxili həyatınız üçün hər şey bir yerdə.', 'Talk to trusted psychologists, follow guided meditation, learn from videos and let PreLife AI support you between sessions — everything for your inner life in one place.', 'Разговоры с проверенными психологами, управляемые медитации, обучающие видео и поддержка PreLife ИИ между сессиями — всё о внутренней жизни в одном месте.'),
  ('sections.meditation.heroTitle', 'Daha sakit zehin, gündə bir sessiya.', 'A calmer mind, one session at a time.', 'Спокойнее ум — по одной сессии.'),
  ('sections.meditation.items.0.desc', 'Günə tələsmədən başlamaq üçün qısa bələdçi meditasiya — bütün günün tonunu müəyyən edir.', 'A short guided meditation to start the day without rush — it sets the tone for everything that follows.', 'Короткая управляемая медитация, чтобы начать день без спешки, — она задаёт тон всему остальному.'),
  ('sections.meditation.items.0.title', '5 dəqiqəlik səhər sakitliyi', '5-minute morning calm', '5 минут утренней тишины'),
  ('sections.meditation.items.1.desc', 'Klinik psixoloq, 12 illik təcrübə. Narahatlıq, stress və yandırılma üçün onlayn sessiyalar.', 'Clinical psychologist, 12 years of practice. Online sessions for anxiety, stress and burnout.', 'Клинический психолог, 12 лет практики. Онлайн-сессии по тревожности, стрессу и выгоранию.'),
  ('sections.meditation.items.1.title', 'Aynur Məmmədova', 'Aynur Mammadova', 'Aynur Mammadova'),
  ('sections.meditation.items.2.desc', 'Yandırılma necə yaranır və onu uzaq saxlayan kiçik vərdişlər haqqında dörd hissəli video silsiləsi.', 'A four-part video series on how burnout builds up and the small habits that keep it away.', 'Серия из четырёх видео о том, как складывается выгорание и какие маленькие привычки его сдерживают.'),
  ('sections.meditation.items.2.title', 'Yandırılmanı anlamaq', 'Understanding burnout', 'Понять выгорание'),
  ('sections.meditation.items.3.desc', 'Əhvalınızı soruşan, məşqlər təklif edən və heç vaxt mühakimə etməyən AI yoldaş.', 'An AI companion that checks in on your mood, suggests exercises and never judges.', 'ИИ-компаньон, который интересуется вашим настроением, предлагает практики и никогда не осуждает.'),
  ('sections.meditation.items.3.title', 'PreLife AI-a sual verin', 'Ask PreLife AI', 'Спросите PreLife ИИ'),
